const DEFAULTS = { category: "all", sort: "newest" };
let filters = { category: "phones", sort: "price" };

function clearFilters(current) {
  current = { ...DEFAULTS }; // rebinds the parameter, nothing else
}

clearFilters(filters);
console.log(filters.category); // phones: the caller's variable is untouched

const DEFAULTS = { category: "all", sort: "newest" };
let filters = { category: "phones", sort: "price" };

function clearedFilters() {
  return { ...DEFAULTS }; // build the new value and hand it back
}

filters = clearedFilters(); // only the variable's owner can reassign it
console.log(filters.category); // all

