function withDefaultSort(query) {
  query.sort ??= "newest"; // mutates the object the caller passed
  return query;
}

const query = { q: "headphones", price: { max: 500 } };
const sorted = withDefaultSort(query);
console.log(query.sort); // newest: the caller's object changed
console.log(sorted === query); // true: one object, two names

const copy = { ...query };
copy.q = "speakers"; // top level was copied
copy.price.max = 900; // nested object is still shared
console.log(query.q, query.price.max); // headphones 900
